/* ArtHub COS runtime bridge. Generated by scripts/build-cos-web.cjs. */
(() => {
  'use strict';
  const cfg = window.ARTHUB_COS_CONFIG || {};
  const majsoulRoot = String(cfg.majsoulAssetsRoot || '').replace(/\/+$/, '');
  const bd2Root = String(cfg.bd2AssetsRoot || '').replace(/\/+$/, '');
  const root = String(cfg.root || '').replace(/\/+$/, '');
  const gameRoot = String(cfg.gameAssetsRoot || '').replace(/\/+$/, '');
  const crosscoreRoot = String(cfg.crosscoreAssetsRoot || '').replace(/\/+$/, '');
  const riichicityRoot = String(cfg.riichicityAssetsRoot || cfg.crosscoreAssetsRoot || "").replace(/\/+$/, "");
  if (!root) return;

  const ASSET_MARKERS = [
    '/riichicity/assets/', '/riichicity/thumbs/', '/riichicity/characters.json',
    '/bd2/spine/', '/nikki/spine/', '/nikki/spine_carved/', '/nikki/audio/',
    '/majsoul/assets_raw/', '/majsoul/web_illustrations/',

    '/azurlane-interaction/animators/', '/azurlane-interaction/assets/live2d/', '/azurlane-interaction/assets/spinepainting/',
    '/azurlane-interaction/audio/', '/azurlane-interaction/catalog/', '/azurlane-interaction/model-audio/', '/azurlane-interaction/models/',
    '/crosscore/spine/', '/crosscore/audio/', '/crosscore-interaction/audio/', '/crosscore-interaction/catalog/',
    '/crosscore-interaction/spine/', '/crosscore-interaction/voices/',
  ];

  const GAME_ASSET_MARKERS = [
    '/azurlane-interaction/animators/', '/azurlane-interaction/assets/live2d/', '/azurlane-interaction/assets/spinepainting/',
    '/azurlane-interaction/audio/', '/azurlane-interaction/catalog/', '/azurlane-interaction/model-audio/', '/azurlane-interaction/models/',
  ];

  const CROSSCORE_ASSET_MARKERS = [
    '/crosscore/spine/', '/crosscore/audio/', '/crosscore-interaction/audio/', '/crosscore-interaction/catalog/',
    '/crosscore-interaction/spine/', '/crosscore-interaction/voices/',
  ];

  // These atlas page names use different casing from the stored textures.
  const MAJSOUL_ATLAS_PAGE_CASE = new Set([
    "/majsoul/assets_raw/myassets/spine/401906/1/Character_XNY_sy_Back.png",
    "/majsoul/assets_raw/myassets/spine/401906/2/Character_XNY_sy_Centre.png",
    "/majsoul/assets_raw/myassets/spine/401906/3/Character_XNY_sy_Front.png",
    "/majsoul/assets_raw/myassets/spine/401906/3/Character_XNY_sy_Front_2.png",
    "/majsoul/assets_raw/myassets/spine/401709/Character_winter_gh.png",
    "/majsoul/assets_raw/myassets/spine/403304/Character_SQQHL_Summer.png",
    "/majsoul/assets_raw/myassets/spine/409502/Character_NFH2.png",
    "/majsoul/assets_raw/myassets/spine/409502/Character_NFH2_2.png",
  ]);

  const PATH_REWRITES = {
    // 页面索引沿用本地的 spine/ 相对路径；COS 里已上传的妮姬目录名是 spine_carved。
    '/nikki/spine/': '/nikki/spine_carved/',
    '/crosscore-interaction/spine/': '/crosscore/spine/',
  };

  function markerPath(pathname) {
    for (const [marker, remote] of Object.entries(PATH_REWRITES)) {
      const at = pathname.indexOf(marker);
      if (at >= 0) return remote + pathname.slice(at + marker.length);
    }
    for (const marker of ASSET_MARKERS) {
      const at = pathname.indexOf(marker);
      if (at >= 0) return pathname.slice(at);
    }
    return null;
  }

  function resolve(input) {
    const source = input instanceof Request ? input.url : String(input);
    const url = new URL(source, location.href);
    if (url.origin !== location.origin) return url.href;
    if (bd2Root) {
      const coverAt = url.pathname.indexOf('/thumbs/bd2/portraits/');
      const bd2Path = coverAt >= 0
        ? '/bd2/portraits' + url.pathname.slice(coverAt)
        : url.pathname.match(/\/bd2\/(?:spine|portraits)\/.*/)?.[0];
      if (bd2Path) return bd2Root + bd2Path + url.search + url.hash;
    }
    const remotePath = markerPath(url.pathname);
    if (!remotePath) return url.href;
    if (majsoulRoot && remotePath.startsWith('/majsoul/')) {
      const key = MAJSOUL_ATLAS_PAGE_CASE.has(remotePath) ? remotePath.toLowerCase() : remotePath;
      return majsoulRoot + key + url.search + url.hash;
    }
    const gameAsset = GAME_ASSET_MARKERS.some(marker => url.pathname.indexOf(marker) >= 0);
    const crosscoreAsset = CROSSCORE_ASSET_MARKERS.some(marker => url.pathname.indexOf(marker) >= 0);
    const riichicityAsset = ['/riichicity/assets/', '/riichicity/thumbs/', '/riichicity/characters.json'].some(marker => url.pathname.indexOf(marker) >= 0);
    const targetRoot = riichicityAsset && riichicityRoot ? riichicityRoot : crosscoreAsset && crosscoreRoot ? crosscoreRoot : gameAsset && gameRoot ? gameRoot : root;
    return targetRoot + remotePath + url.search + url.hash;
  }

  window.ARTHUB_COS_ROOT = root;
  window.ARTHUB_COS_RESOLVE = resolve;
  const nativeFetch = window.fetch.bind(window);
  window.fetch = (input, init) => {
    let target;
    try { target = resolve(input); } catch { return nativeFetch(input, init); }
    const request = input instanceof Request ? new Request(target, input) : target;
    return nativeFetch(request, init);
  };

  // Spine's WebGL runtime uses XMLHttpRequest for atlas and texture files.
  // Rewrite those requests too; changing fetch alone leaves the viewer's
  // index working while every model reports a 404 from the static host.
  if (window.XMLHttpRequest && window.XMLHttpRequest.prototype && !window.XMLHttpRequest.prototype.__arthubCosPatched) {
    const nativeOpen = window.XMLHttpRequest.prototype.open;
    window.XMLHttpRequest.prototype.open = function(method, url, ...rest) {
      let target = url;
      try { target = resolve(url); } catch {}
      return nativeOpen.call(this, method, target, ...rest);
    };
    window.XMLHttpRequest.prototype.__arthubCosPatched = true;
  }

  // Spine's browser loader creates HTMLImageElement instances and assigns
  // image.src directly for atlas page PNGs.  fetch/XHR interception does not
  // see that navigation, so rewrite the native src setter as well.
  if (window.HTMLImageElement && window.HTMLImageElement.prototype && !window.HTMLImageElement.prototype.__arthubCosPatched) {
    const descriptor = Object.getOwnPropertyDescriptor(window.HTMLImageElement.prototype, 'src');
    if (descriptor && typeof descriptor.set === 'function') {
      const nativeSet = descriptor.set;
      const patchedSet = function(value) {
        let target = value;
        if (value !== null && value !== undefined) {
          try { target = resolve(value); } catch {}
        }
        return nativeSet.call(this, target);
      };
      Object.defineProperty(window.HTMLImageElement.prototype, 'src', { ...descriptor, set: patchedSet });
      window.HTMLImageElement.prototype.__arthubCosPatched = true;
    }
  }


  if (window.HTMLMediaElement && window.HTMLMediaElement.prototype && !window.HTMLMediaElement.prototype.__arthubCosPatched) {
    const descriptor = Object.getOwnPropertyDescriptor(window.HTMLMediaElement.prototype, 'src');
    if (descriptor && typeof descriptor.set === 'function') {
      const nativeSet = descriptor.set;
      const patchedSet = function(value) {
        let target = value;
        if (value !== null && value !== undefined) {
          try { target = resolve(value); } catch {}
        }
        return nativeSet.call(this, target);
      };
      Object.defineProperty(window.HTMLMediaElement.prototype, 'src', { ...descriptor, set: patchedSet });
      window.HTMLMediaElement.prototype.__arthubCosPatched = true;
    }
  }

  if (typeof window.Audio === 'function' && !window.Audio.__arthubCosPatched) {
    const NativeAudio = window.Audio;
    const PatchedAudio = function(source) {
      return new NativeAudio(source === undefined ? undefined : resolve(source));
    };
    PatchedAudio.prototype = NativeAudio.prototype;
    Object.setPrototypeOf(PatchedAudio, NativeAudio);
    PatchedAudio.__arthubCosPatched = true;
    window.Audio = PatchedAudio;
  }
})();
